"""模块单测环境。

模块作者不编整颗内核也能验证自己的 hook 逻辑：devkit 生成一个**独立**的
C 测试程序，用桩件替代 KernelSU 依赖，编译并运行。

关键点：同一份 `<module>/tests/*.c` 既可以放进仓库做回归，也可以由
`ksuhook dev` 一键编译，因此模块作者的单测与 CI 的测试是同一条路径。
"""

from __future__ import annotations

import shutil
import subprocess
import tempfile
from dataclasses import dataclass
from pathlib import Path

from .errors import SdkError
from .spec import Module

SHIM_DIR = Path(__file__).resolve().parent.parent / "devkit" / "shim"

STUB = """\
/* Generated by ksuhook devkit: weak fallbacks so the payload links on the host. */
#include <linux/sched.h>

static struct task_struct ksuhook_idle_stub = {.pid = 0, .tgid = 0};
struct task_struct *ksuhook_current __attribute__((weak)) = &ksuhook_idle_stub;
void ksuhook_test_log(const char *fmt, ...) __attribute__((weak));
void ksuhook_test_log(const char *fmt, ...) { (void)fmt; }
"""


@dataclass(frozen=True)
class DevResult:
    ok: bool
    output: str
    command: str


def _cc() -> str | None:
    for candidate in ("cc", "gcc", "clang"):
        found = shutil.which(candidate)
        if found:
            return found
    return None


def build_and_run(module: Module, keep: Path | None = None) -> DevResult:
    """编译并运行模块自带单测。没有 tests/ 时返回 ok=True 并说明跳过原因。"""
    cc = _cc()
    if cc is None:
        return DevResult(ok=True, output="未找到 C 编译器，跳过模块单测", command="")

    if module.tests_dir is None:
        return DevResult(ok=True, output="模块没有 tests/，跳过单测", command="")

    tests = sorted(module.tests_dir.glob("*.c"))
    if not tests:
        return DevResult(ok=True, output="tests/ 下没有 C 用例，跳过单测", command="")

    work = Path(tempfile.mkdtemp(prefix="ksuhook-dev-")) if keep is None else keep
    try:
        stub_path = work / "ksuhook_stub.c"
        stub_path.write_text(STUB, encoding="utf-8")

        # tests/ 下每个 .c 都是一个独立的测试程序：全部编译、全部运行，
        # 不能只跑第一个然后当作整个模块通过了。
        outputs: list[str] = []
        commands: list[str] = []
        for main_file in tests:
            binary = work / f"module_test_{main_file.stem}"
            command = [
                cc,
                "-std=gnu11",
                "-O1",
                "-Wall",
                "-Wextra",
                "-Wno-unused-parameter",
                "-I",
                str(SHIM_DIR),
                "-I",
                str(module.root / "src"),
                "-o",
                str(binary),
                str(main_file),
                *(str(p) for p in module.sources),
                str(stub_path),
            ]
            proc = subprocess.run(command, capture_output=True, text=True)
            shown = " ".join(command)
            commands.append(shown)
            if proc.returncode != 0:
                return DevResult(
                    ok=False,
                    output=f"[{main_file.name}] 编译失败\n{proc.stderr}",
                    command=shown,
                )
            run = subprocess.run([str(binary)], capture_output=True, text=True)
            text = run.stdout + run.stderr
            outputs.append(text if len(tests) == 1 else f"[{main_file.name}] {text.strip()}")
            if run.returncode != 0:
                return DevResult(ok=False, output="\n".join(outputs), command=shown)

        return DevResult(ok=True, output="\n".join(outputs), command=" && ".join(commands))
    except OSError as exc:
        raise SdkError(f"无法执行编译器: {exc}", str(module.root)) from exc
    finally:
        if keep is None:
            shutil.rmtree(work, ignore_errors=True)
